NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Nahum'

CHAPTERS = {
    1: {
        1: 'Weissagung über Niniveh. Buch des Gesichtes Nachums, des Elkoschiters.',
        2: 'Ein eifernder und rächender Gott ist Jehovah. Ein Rächer ist Jehovah, ist ergrimmt, ein Rächer ist Jehovah an Seinen Drängern, und trägt nach Seinen Feinden.',
        3: 'Jehovah ist langmütig und groß an Kraft und läßt nicht ungestraft. Jehovah, im Sturmwind und im Wetter ist Sein Weg, und die Wolke ist Seiner Füße Staub.',
        4: 'Er bedroht das Meer und trocknet es aus, und läßt vertrocknen alle Flüsse; Baschan verschmachtet und Karmel und die Blüte des Libanon verschmachtet.',
        5: 'Berge erbeben vor Seinem Angesicht, und die Hügel zerfließen, und vor Seinem Angesicht erhebt sich die Erde und die Welt, und die darin wohnen.',
        6: 'Wer wird stehen vor Seinem Unwillen? Und wer wird vor Seines Zornes Entbrennen bestehen? Sein Grimm ergießt sich wie Feuer, und die Felsen zerspringen vor Ihm.',
        7: 'Gut ist Jehovah als Stärke am Tag der Drangsal und kennt die, so auf Ihn sich verlassen.',
        8: 'Durch überströmende Flut macht Er ihrem Ort ein Ende, und Seinen Feinden setzt nach die Finsternis.',
        9: 'Was erdenkt ihr wider Jehovah? Eine Vollendung macht Er. Die Drangsal ersteht nicht zweimal.',
        10: 'Wie in Dornen verstrickt und wie vom Zechen berauscht, werden sie wie die verdorrte Stoppel völlig aufgefressen.',
        11: 'Aus dir ging aus, der Böses wider Jehovah erdachte, Ruchloses beraten hatte.',
        12: 'So spricht Jehovah: Und kommen sie in Vollzahl, und viele, so sollen sie weggeschoren werden und vorbei sein. Und habe Ich dich niedergedrückt, so werde Ich dich nicht mehr niederdrücken.',
        13: 'Und nun breche Ich sein Jochholz ab von dir, und will abreißen deine Bande.',
        14: 'Und Jehovah gebeut über dir: Nicht soll hinfort von deinem Samen mehr gesät werden. Vom Hause deines Gottes rotte Ich das Schnitzbild und das Gußbild aus, Ich setze dir dein Grab, denn du wardst gering.',
    },
    2: {
        1: 'Siehe, auf den Bergen die Füße des Heilsboten, der Frieden verkündigte. Feiere du deine Feste, Jehudah, entrichte deine Gelübde; denn durch dich zieht nicht wiederum hindurch der Belial, er ist ganz ausgerottet.',
        2: 'Herauf zieht der Zerstreuer vor dein Angesicht. Bewahrt das Bollwerk! Spähe auf den Weg, mache fest die Lenden, verstärke sehr die Kraft.',
        3: 'Denn Jehovah wendet zurück den Stolz Jakobs wie den Stolz Israels; denn die Ausleerer haben ausgeleert, und ihre Weinranken haben sie verdorben.',
        4: 'Die Tartsche seiner Helden ist gerötet, die Männer der Tapferkeit sind im Scharlach; im Feuer der Fackeln ist der Streitwagen, am Tage, da er sich bereit macht, und die Lanzen geschwungen werden.',
        5: 'In den Gassen rasen die Streitwagen, sie rennen dahin auf den Straßen, ihr Aussehen ist wie das der Fackeln, wie die Blitze fahren sie.',
        6: 'Er gedenkt seiner Stattlichen, sie straucheln in ihrem Gehen, sie eilen nach der Mauer. Die Bedeckung wird bereit gemacht.',
        7: 'Die Tore der Flüsse werden geöffnet, und der Palast zerfließt.',
        8: 'Es ist beschlossen: Sie wird gefangen hinausgeführt, und ihre Mägde wehklagen wie die Stimme der Tauben, und schlagen auf ihr Herz.',
        9: 'Und Niniveh war wie ein Teich von Wassern von den Tagen an, da es bestand, und sie fliehen: Stehet, stehet! Und niemand wendet sich um.',
        10: 'Raubt Silber, raubt Gold, und kein Ende des Vorrats, eine Herrlichkeit an allen den kostbarsten Gefäßen.',
        11: 'Leerheit und Ausleerung und Ausräumung, und ein zerschmelzendes Herz, und Schlottern der Knie, und Pein in allen Landen, und alle Angesichter ziehen ihr Wangenrot ein.',
        12: 'Wo ist der Löwen Wohnstätte und die Weide der jungen Löwen, wo der Löwe, der alte Löwe und das Junge des Löwen sich ergingen, und niemand sie aufscheuchte!',
        13: 'Der Löwe zerfleischte genug für seinen Jungen, und erwürgte für seine alte Löwinnen, und füllte seine Höhlen mit dem Zerfleischten und seine Wohnstätte mit dem, was er zerfleischt. Siehe, Ich bin wider dich, spricht Jehovah der Heerscharen, und laß brennen mit Rauch seine Streitwagen, und deine jungen Löwen fresse das Schwert, und Ich rotte aus von der Erde dein Zerfleischtes, daß deiner Boten Stimme man nimmer hören soll.',
    },
    3: {
        1: 'Wehe der Stadt des Blutes! Ganz ist sie von Lug, von Räuberei erfüllt; sie weicht nicht vom Zerfleischen.',
        2: 'Der Peitsche Stimme und die Stimme des Rasselns der Räder, und es wiehert das Roß und hüpft der Streitwagen.',
        3: 'Der Reiter, der heraufzieht, und die Flamme des Schwertes, und der Blitz des Spießes, und die vielen Erschlagenen, und der Haufen der Leichen, und kein Ende der Leiber, sie straucheln über ihre Leiber!',
        4: 'Wegen der Menge der Buhlereien der Buhlerin, gut an Gnade, der Meisterin der Zaubereien, die mit ihren Buhlereien Völkerschaften verkaufte, und Familien mit ihren Zaubereien.',
        5: 'Siehe, Ich bin wider dich, spricht Jehovah der Heerscharen, und will deine Säume aufdecken über dein Angesicht, und laß die Völkerschaften deine Blöße und die Königreiche deine Unehre sehen;',
        6: 'Und will Abscheuliches auf dich werfen, dich verunehren und dich zur Schau stellen.',
        7: 'Und es soll geschehen, daß alle, die dich sehen, von dir entfliehen und sagen: Verheeret ist Niniveh! Wer wird ihr Beileid zeigen, woher soll ich einen Tröster für dich suchen?',
        8: 'Bist du besser denn No-Amon, das in den Nilströmen lag, Wasser rings um sie her; deren Vermögen das Meer war, und ihre Mauer aus dem Meere?',
        9: 'Kusch war seine Macht und Ägypten, und war kein Ende; Put und Lubim waren dir zum Beistand.',
        10: 'Auch sie ging in Verbannung, in die Gefangenschaft; auch wurden ihre Kindlein zerschmettert an aller Gassen Ecken; um ihre Herrlichen warfen sie das Los, und all ihre Großen wurden mit Ketten gefesselt.',
        11: 'Auch du wirst trunken, wirst dich verbergen und eine Schutzwehr suchen vor dem Feind.',
        12: 'All deine Festungen sind Feigenbäume mit Frühfeigen; so man sie schüttelt, fallen sie in den Mund des Essenden.',
        13: 'Siehe, dein Volk innerhalb deiner sind Weiber, deinen Feinden öffnet man die Tore deines Landes, Feuer frißt deine Riegel.',
        14: 'Schöpfe dir Wasser der Belagerung. Mache stark deine Festungen. Komme in den Kot und zerstampfe den Ton, mache den Ziegelofen fest.',
        15: 'Dort wird das Feuer dich fressen, das Schwert dich ausrotten, dich fressen wie die Grille; mache dich zahlreich wie die Grille, zahlreich wie die Heuschrekke.',
        16: 'Du vermehrst deine Kaufleute mehr als des Himmels Sterne: die Grille rückt aus und fliegt davon.',
        17: 'Deine Diademträger sind wie die Heuschrecken, und deine Befehlshaber wie ein Heuschreckenschwarm eines Heuschreckenschwarms; sie lagern am kalten Tage an den Mauern. Geht die Sonne auf, so entfliehen sie, und man weiß nicht den Ort, wo sie gewesen.',
        18: 'Es schlummern deine Hirten, König Aschurs, da liegen deine Stattlichen, auf die Berge ist dein Volk zerstoben, und keiner bringt sie zusammen.',
        19: 'Für deinen Bruch gibt es kein Verharschen, heillos ist dein Schlag. Jeder, der das Gerücht von dir hört, klatscht über dir die Hände; denn über wen ist nicht beständig Böses von dir übergeflossen?',
    },
}
